+
+  it('a not-ended node returns null', () => {
+    setStore({ derivedIssueStateByIssueId: { 'PAN-1': derived() } });
+    const { result } = renderHook(() => useSessionNodeOutcome(node({ presence: 'active' }), 'PAN-1'));
